#include <stdio.h>
int main(void) {
  int limit, price, amount, extra, rebate;
  scanf("%d%d%d%d%d", &limit, &price, &amount, &extra, &rebate);
  int used = price * amount + extra - rebate;
  int remain = limit - used;
  printf("used=%d,remain=%d\n", used, remain);
